-- Test TBD: full database setup for a NEW project. Run once in Supabase (SQL Editor > New query > paste > Run).
-- Already set up earlier? Run supabase-update.sql instead.

-- Generated by tools/build-sql.mjs from the files in sql/ and js/content. Edit those, then run: npm run sql

-- New projects only: the player profile table.
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  username text not null check (username ~ '^[A-Za-z0-9_]{3,16}$'),
  email text not null,
  level int not null default 1,
  xp int not null default 0,
  gold bigint not null default 0,
  best_wave int not null default 0,
  runs int not null default 0,
  talents text[] not null default '{}',
  levels_cleared int not null default 0,
  frontier_wave int not null default 0,
  lineup text[] not null default '{warrior,ranger,mage}',
  equipment jsonb not null default '{}',
  created_at timestamptz not null default now()
);
-- No two accounts may share a username or an email (case-insensitive).
create unique index profiles_username_key on public.profiles (lower(username));
create unique index profiles_email_key on public.profiles (lower(email));

alter table public.profiles enable row level security;
-- Players can read only their own row (their email stays private). Changes happen only through the functions below.
create policy "read own profile" on public.profiles
  for select to authenticated using (auth.uid() = id);

-- ===== Username rules: reserved and blocked names =====
create table if not exists public.blocked_names (
  term text primary key,
  mode text not null check (mode in ('exact', 'contains'))
);
alter table public.blocked_names enable row level security;   -- no policies: players cannot read or change it
-- Starter list. Add rows to block more. Terms are matched after swapping 0/1/i look-alikes (0->o, 1->l, i->l).
on conflict (term) do nothing;

-- ===== Talent trees (so the server can check talent saves) =====
create table if not exists public.talent_nodes (
  id text primary key,
  tree text not null,
  is_root boolean not null default false
);
create table if not exists public.talent_links (
  a text not null references public.talent_nodes (id) on delete cascade,
  b text not null references public.talent_nodes (id) on delete cascade,
  primary key (a, b)
);
-- Reward bonuses a node gives at the end of a match (0.1 = +10%), used by finish_run.
alter table public.talent_nodes add column if not exists reward_gold numeric not null default 0;
alter table public.talent_nodes add column if not exists reward_xp numeric not null default 0;
alter table public.talent_nodes add column if not exists reward_loot numeric not null default 0;
-- Treasure Hunter talents: item rarity luck (like relic luck) and the extra chance of each further item bonus.
alter table public.talent_nodes add column if not exists reward_rarity numeric not null default 0;
alter table public.talent_nodes add column if not exists reward_extra numeric not null default 0;
alter table public.talent_nodes enable row level security;
alter table public.talent_links enable row level security;

-- ===== Run records: every saved run must come from a run the server saw start =====
create table if not exists public.runs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  stage int not null check (stage between 1 and 5),
  started_at timestamptz not null default now(),
  finished_at timestamptz
);
create index if not exists runs_user_idx on public.runs (user_id, finished_at);
alter table public.runs enable row level security;
alter table public.runs add column if not exists loadout jsonb;   -- the lineup and equipment a run started with (for future checks)

-- ===== Heroes and items (so the server can check lineups and equipment) =====
create table if not exists public.hero_classes (
  id text primary key
);
create table if not exists public.item_types (
  id text primary key,
  slot text not null,
  droppable boolean not null default true
);
-- Every item a player owns. Items are created only by finish_run (drops) and are never edited by players directly.
create table if not exists public.player_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  item_type text not null references public.item_types (id),
  created_at timestamptz not null default now()
);
create index if not exists player_items_user_idx on public.player_items (user_id);
-- Rarity (0 Common, 1 Uncommon, 2 Rare, 3 Epic) and bonuses (relic names, no repeats, at most 4), rolled by finish_run.
-- Items from before this existed stay Common with no bonuses.
alter table public.player_items add column if not exists rarity int not null default 0 check (rarity between 0 and 3);
alter table public.player_items add column if not exists bonuses text[] not null default '{}';
-- The relics an item bonus can be (generated from js/content/items.js).
create table if not exists public.item_bonuses (
  id text primary key
);
alter table public.item_bonuses enable row level security;
alter table public.hero_classes enable row level security;
alter table public.item_types enable row level security;
alter table public.player_items enable row level security;
drop policy if exists "read own items" on public.player_items;
create policy "read own items" on public.player_items
  for select to authenticated using (auth.uid() = user_id);

-- ===== Game content (generated from js/content by tools/build-sql.mjs; do not edit by hand) =====
-- Talent trees. Links are stored in both directions.
delete from public.talent_links;
on conflict (id) do update set tree = excluded.tree, is_root = excluded.is_root, reward_gold = excluded.reward_gold, reward_xp = excluded.reward_xp, reward_loot = excluded.reward_loot, reward_rarity = excluded.reward_rarity, reward_extra = excluded.reward_extra;
delete from public.talent_nodes where id <> all (array['t4_root', 't4_p0', 't4_energy_s', 't4_energy_n', 't4_energy_a1', 't4_energy_a2', 't4_energy_a3', 't4_energy_b1', 't4_energy_b2', 't4_energy_b3', 't4_p1', 't4_p2', 't4_p3', 't4_p4', 't4_martial_s', 't4_martial_n', 't4_martial_a1', 't4_martial_a2', 't4_martial_b1', 't4_martial_b2', 't4_p5', 't4_sunder_s', 't4_sunder_n', 't4_sunder_a1', 't4_sunder_a2', 't4_sunder_a3', 't4_sunder_b1', 't4_sunder_b2', 't4_sunder_b3', 't4_p6', 't4_p7', 't4_p8', 't4_p9', 't4_marksman_s', 't4_marksman_n', 't4_marksman_a1', 't4_marksman_a2', 't4_marksman_b1', 't4_marksman_b2', 't4_p10', 't4_toxins_s', 't4_toxins_n', 't4_toxins_a1', 't4_toxins_a2', 't4_toxins_a3', 't4_toxins_b1', 't4_toxins_b2', 't4_toxins_b3', 't4_p11', 't4_p12', 't4_p13', 't4_p14', 't4_might_s', 't4_might_n', 't4_might_a1', 't4_might_a2', 't4_might_b1', 't4_might_b2', 't4_p15', 't4_fire_s', 't4_fire_n', 't4_fire_a1', 't4_fire_a2', 't4_fire_a3', 't4_fire_b1', 't4_fire_b2', 't4_fire_b3', 't4_p16', 't4_p17', 't4_p18', 't4_p19', 't4_precision_s', 't4_precision_n', 't4_precision_a1', 't4_precision_a2', 't4_precision_b1', 't4_precision_b2', 't4_p20', 't4_cold_s', 't4_cold_n', 't4_cold_a1', 't4_cold_a2', 't4_cold_a3', 't4_cold_b1', 't4_cold_b2', 't4_cold_b3', 't4_p21', 't4_p22', 't4_p23', 't4_p24', 't4_sorcery_s', 't4_sorcery_n', 't4_sorcery_a1', 't4_sorcery_a2', 't4_sorcery_b1', 't4_sorcery_b2', 't4_p25', 't4_lightning_s', 't4_lightning_n', 't4_lightning_a1', 't4_lightning_a2', 't4_lightning_a3', 't4_lightning_b1', 't4_lightning_b2', 't4_lightning_b3', 't4_p26', 't4_p27', 't4_p28', 't4_p29', 't4_training_s', 't4_training_n', 't4_training_a1', 't4_training_a2', 't4_training_b1', 't4_training_b2', 't4_p30', 't4_fortune_s', 't4_fortune_n', 't4_fortune_a1', 't4_fortune_a2', 't4_fortune_a3', 't4_fortune_b1', 't4_fortune_b2', 't4_fortune_b3', 't4_p31', 't4_p32', 't4_p33', 't4_p34', 't4_tempo_s', 't4_tempo_n', 't4_tempo_a1', 't4_tempo_a2', 't4_tempo_b1', 't4_tempo_b2', 't4_p35', 't